//! GPT-SoVITS 整合包启动器。
//!
//! Ink 只支持**本地** GSOV, 并由自己负责拉起进程, 以保证参考音频与模型路径
//! 在服务端本机可见。启动方式有三类, 覆盖从"开箱即用"到"完全自定义":
//!
//! * [`LaunchMode::Embedded`] - 整合包自带运行时 (`runtime\python.exe`), 依赖自包含, 默认加 `-I` 隔离;
//! * [`LaunchMode::Python`] - 用户自己的 Python (conda / 系统)。**不能加 `-I`**: 隔离模式会屏蔽用户级
//!   site-packages, 而部分依赖 (如 `click`) 恰恰装在那里;
//! * [`LaunchMode::Command`] - 完全自定义命令 (bat / ps1 / 任意可执行文件), Ink 只负责启动与收尸。

use std::path::{Path, PathBuf};

use serde::{Deserialize, Serialize};

/// 默认端口
pub const DEFAULT_PORT: u16 = 9880;
/// 默认绑定地址 (仅本地)
pub const DEFAULT_HOST: &str = "127.0.0.1";
/// 默认控制脚本
pub const DEFAULT_SCRIPT: &str = "api_v2.py";
/// 默认推理配置
pub const DEFAULT_INFER_CONFIG: &str = "GPT_SoVITS/configs/tts_infer.yaml";

/// 启动方式
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", tag = "kind")]
pub enum LaunchMode {
    /// 整合包自带运行时
    Embedded { program: String },
    /// 外部 Python 解释器
    Python { program: String },
    /// 自定义命令 (不经过 Python 参数拼装)
    Command { program: String, args: Vec<String> },
}

impl LaunchMode {
    /// 是否启用 Python 隔离模式 (`-I`)
    pub fn isolated(&self) -> bool {
        matches!(self, LaunchMode::Embedded { .. })
    }
}

/// 启动配置
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct LaunchConfig {
    /// 整合包根目录 (同时作为工作目录)
    pub root: String,
    /// 启动方式
    pub mode: LaunchMode,
    /// API 绑定地址
    pub host: String,
    /// API 端口
    pub port: u16,
    /// 控制脚本 (相对整合包根)
    pub script: String,
    /// 推理配置 (相对整合包根)
    pub infer_config: String,
    /// 额外的解释器参数 (自定义启动方式下忽略)
    #[serde(default)]
    pub extra_args: Vec<String>,
}

/// 整合包探测结果 (供 UI 预填默认值)
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct DetectedRuntime {
    /// 是否为可用的整合包根目录
    pub valid: bool,
    /// 内置运行时路径
    pub embedded_python: Option<String>,
    /// 内置运行时是否存在
    pub has_embedded_python: bool,
    /// 控制脚本是否存在
    pub has_script: bool,
    /// 推理配置是否存在
    pub has_infer_config: bool,
    /// 探测到的问题 (供 UI 提示)
    pub issues: Vec<String>,
}

/// 探测整合包目录, 给出默认启动配置所需的全部信息
pub fn detect(root: &Path) -> DetectedRuntime {
    let mut issues = Vec::new();

    if !root.is_dir() {
        return DetectedRuntime {
            valid: false,
            embedded_python: None,
            has_embedded_python: false,
            has_script: false,
            has_infer_config: false,
            issues: vec!["目录不存在".into()],
        };
    }

    let embedded = root.join("runtime").join("python.exe");
    let has_embedded = embedded.is_file();
    if !has_embedded {
        issues.push("未见整合包内置运行时 (runtime\\python.exe), 请指定外部 Python 或自定义命令".into());
    }

    let has_script = root.join(DEFAULT_SCRIPT).is_file();
    if !has_script {
        issues.push(format!("未见控制脚本 {DEFAULT_SCRIPT}"));
    }

    let has_infer_config = root.join(DEFAULT_INFER_CONFIG).is_file();
    if !has_infer_config {
        issues.push(format!("未见推理配置 {DEFAULT_INFER_CONFIG}"));
    }

    DetectedRuntime {
        valid: has_script,
        embedded_python: has_embedded.then(|| embedded.display().to_string()),
        has_embedded_python: has_embedded,
        has_script,
        has_infer_config,
        issues,
    }
}

/// 按探测结果构造默认启动配置
pub fn default_config(root: &Path, detected: &DetectedRuntime) -> LaunchConfig {
    let mode = match &detected.embedded_python {
        Some(program) => LaunchMode::Embedded {
            program: program.clone(),
        },
        None => LaunchMode::Python {
            program: "python".into(),
        },
    };
    LaunchConfig {
        root: root.display().to_string(),
        mode,
        host: DEFAULT_HOST.into(),
        port: DEFAULT_PORT,
        script: DEFAULT_SCRIPT.into(),
        infer_config: DEFAULT_INFER_CONFIG.into(),
        extra_args: Vec::new(),
    }
}

/// 启动命令
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LaunchCommand {
    pub program: String,
    pub args: Vec<String>,
    pub cwd: PathBuf,
}

impl LaunchConfig {
    /// 拼装实际启动命令
    pub fn build_command(&self) -> LaunchCommand {
        let cwd = PathBuf::from(&self.root);
        let (program, mut args) = match &self.mode {
            LaunchMode::Embedded { program } | LaunchMode::Python { program } => {
                let mut args: Vec<String> = Vec::new();
                if self.mode.isolated() {
                    args.push("-I".into());
                }
                args.push(self.script.clone());
                args.push("-a".into());
                args.push(self.host.clone());
                args.push("-p".into());
                args.push(self.port.to_string());
                args.push("-c".into());
                args.push(self.infer_config.clone());
                args.extend(self.extra_args.iter().cloned());
                (program.clone(), args)
            }
            LaunchMode::Command { program, args } => (program.clone(), args.clone()),
        };
        args.shrink_to_fit();
        LaunchCommand {
            program,
            args,
            cwd,
        }
    }
}

/// 用于日志面板的换行切分。
///
/// GSOV 依赖的 `tqdm` 进度条用 `\r` 覆盖同一行且**不换行**, 直接按 `\n` 收集会把
/// 整个推理过程的进度条拼成一条超长文本。这里按 `\n` / `\r` 任意一个切分, 并忽略空段。
#[derive(Debug, Default)]
pub struct LineSplitter {
    buffer: String,
}

impl LineSplitter {
    pub fn new() -> Self {
        Self::default()
    }

    /// 送入一段输出, 返回其中完整的行
    pub fn push(&mut self, chunk: &str) -> Vec<String> {
        let mut lines = Vec::new();
        for ch in chunk.chars() {
            match ch {
                '\n' | '\r' => {
                    let line = std::mem::take(&mut self.buffer);
                    let trimmed = line.trim();
                    if !trimmed.is_empty() {
                        lines.push(trimmed.to_string());
                    }
                }
                other => {
                    self.buffer.push(other);
                    // 防御性截断: 进度条可能极长且无分隔符
                    if self.buffer.len() > 4096 {
                        let line = std::mem::take(&mut self.buffer);
                        lines.push(line);
                    }
                }
            }
        }
        lines
    }

    /// 取走缓冲区中的残留内容 (进程结束时调用)
    pub fn flush(&mut self) -> Option<String> {
        let line = std::mem::take(&mut self.buffer);
        let trimmed = line.trim();
        (!trimmed.is_empty()).then(|| trimmed.to_string())
    }
}

